param([string]$OutputDirectory='.local/revalidation/M191-first-run',[string]$ScratchPrefix='M191')
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $MyInvocation.MyCommand.Path | Split-Path -Parent
$out=Join-Path $root $OutputDirectory
if((Test-Path -LiteralPath $out)-and @(Get-ChildItem -LiteralPath $out -Force).Count-gt0){throw "Refusing to overwrite nonempty output: $out"}
if(-not(Test-Path -LiteralPath $out)){New-Item -ItemType Directory -Path $out|Out-Null}
function Hash191([string]$p){(Get-FileHash -LiteralPath (Join-Path $root $p) -Algorithm SHA256).Hash.ToLowerInvariant()}
$m186='Tools/search_m186_public_route.ps1';$m188='Tools/search_m188_dining_set_placement.ps1';$spec='Architecture/Kitchen_Dining_Porch_Specs.md';$selected='Architecture/Selected_Design_Iteration_2026-10-27/study.json';$bath='Architecture/Direction_D_BathFirst_Adjacency_Study_2026-10-27/study.json'
$hashes=[ordered]@{};foreach($p in @($m186,$m188,$spec,$selected,$bath)){ $hashes[$p]=Hash191 $p }
if($hashes[$selected]-ne'516d6d17e5b6ed6c8ec8cbf7a925cc67c5cc1c0ada194c22ea3fa124e2bb72bb'){throw 'Selected-D source changed; refusing this comparison.'}
$m186Source=[IO.File]::ReadAllText((Join-Path $root $m186));$needle='$obstacles=@($entry,$pantry,$west,$east,$counter,$island,$stools,$halfwall,$wallReturn,$table)+$chairs+$porchWalls'
if(([regex]::Matches($m186Source,[regex]::Escape($needle))).Count-ne1){throw 'M186 obstacle declaration changed; refusing unreviewed generation.'}
$cases=@([pscustomobject]@{id='baseline';dx=0.0;dy=0.0},[pscustomobject]@{id='east_1ft';dx=1.0;dy=0.0},[pscustomobject]@{id='north_1ft';dx=0.0;dy=1.0})
$rows=New-Object System.Collections.Generic.List[object];$caseDetails=New-Object System.Collections.Generic.List[object]
foreach($c in $cases){
    $dx=[double]$c.dx;$dy=[double]$c.dy
    $tableX=3+$dx;$tableY=17.5+$dy
    $snippet=@"
`$table=NewRect186 $tableX $tableY 5 3 'dining-table'
`$chairs=@((NewRect186 $(3.5+$dx) $(15.8333333333+$dy) 1.5 1.6666666667 'south-chair-1'),(NewRect186 $(6+$dx) $(15.8333333333+$dy) 1.5 1.6666666667 'south-chair-2'),(NewRect186 $(1.3333333333+$dx) $(17.5+$dy) 1.6666666667 1.5 'west-chair-1'),(NewRect186 $(1.3333333333+$dx) $(19+$dy) 1.6666666667 1.5 'west-chair-2'))
`$pullouts=@((NewRect186 $(3.5+$dx) $(14.5+$dy) 1.5 3 'south-chair-1-pullout-36in'),(NewRect186 $(6+$dx) $(14.5+$dy) 1.5 3 'south-chair-2-pullout-36in'),(NewRect186 $dx $(17.5+$dy) 3 1.5 'west-chair-1-pullout-36in'),(NewRect186 $dx $(19+$dy) 3 1.5 'west-chair-2-pullout-36in'))
`$obstacles=@(`$entry,`$pantry,`$west,`$east,`$counter,`$island,`$stools,`$halfwall,`$wallReturn,`$table)+`$chairs+`$pullouts+`$porchWalls
"@
    $temp=Join-Path (Split-Path (Join-Path $root $m186) -Parent) ('m191-generated-'+[guid]::NewGuid().ToString('N')+'.ps1')
    $sub='.local/revalidation/'+$ScratchPrefix+'-'+$c.id;$full=Join-Path $root $sub
    if((Test-Path -LiteralPath $full)-and @(Get-ChildItem -LiteralPath $full -Force).Count-gt0){throw "Refusing to overwrite scratch output: $full"}
    try{[IO.File]::WriteAllText($temp,$m186Source.Replace($needle,$snippet.TrimEnd()),(New-Object Text.UTF8Encoding($false)));& $temp -OutputDirectory $sub}finally{if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force}}
    $result=Get-Content (Join-Path $full 'm186-route-search.json') -Raw|ConvertFrom-Json
    $bodyRects=@((New-Object psobject -Property @{x=3.5+$dx;y=15.8333333333+$dy;w=1.5;d=1.6666666667}), (New-Object psobject -Property @{x=6+$dx;y=15.8333333333+$dy;w=1.5;d=1.6666666667}), (New-Object psobject -Property @{x=1.3333333333+$dx;y=17.5+$dy;w=1.6666666667;d=1.5}), (New-Object psobject -Property @{x=1.3333333333+$dx;y=19+$dy;w=1.6666666667;d=1.5}))
    $pullRects=@((New-Object psobject -Property @{x=3.5+$dx;y=14.5+$dy;w=1.5;d=3}), (New-Object psobject -Property @{x=6+$dx;y=14.5+$dy;w=1.5;d=3}), (New-Object psobject -Property @{x=$dx;y=17.5+$dy;w=3;d=1.5}), (New-Object psobject -Property @{x=$dx;y=19+$dy;w=3;d=1.5}))
    $inside=@($bodyRects+$pullRects|Where-Object{$_.x-lt-1e-8-or$_.y-lt(14-1e-8)-or$_.x+$_.w-gt(11+1e-8)-or$_.y+$_.d-gt(24+1e-8)}).Count-eq0
    $rows.Add([pscustomobject]@{case=$c.id;translation_x_ft=$dx;translation_y_ft=$dy;path_found=[bool]$result.search.path_found;route_length_ft=$result.search.route_length_ft;turn_count=$result.search.route_turn_count;reachable_nodes=$result.search.centerline_bounds.reached_node_count;nearest_porch_door_ft=$result.search.centerline_bounds.nearest_reachable_to_porch_door.distance_manhattan_ft;all_bodies_and_pullouts_inside_11_by_10=$inside;pullout_proxy_count=$pullRects.Count;grid_step_ft=$result.search.grid_step_ft;route_width_in=$result.search.route_width_in})
    $caseDetails.Add([pscustomobject]@{case=$c.id;translation_ft=@($dx,$dy);result=$result.status;path_found=[bool]$result.search.path_found;path_length_ft=$result.search.route_length_ft;turns=$result.search.route_turn_count;reached_nodes=$result.search.centerline_bounds.reached_node_count;nearest_to_porch_ft=$result.search.centerline_bounds.nearest_reachable_to_porch_door.distance_manhattan_ft;chair_bodies=$bodyRects;pullout_use_envelopes=$pullRects;route_waypoints=$result.search.compressed_waypoints_ft;blocking_frontier=$result.search.centerline_bounds.blocked_frontier_edges})
}
$bathData=Get-Content (Join-Path $root $bath) -Raw|ConvertFrom-Json;$b=@($bathData.selection.main_public_bath.search_windows|Where-Object id -eq 'east_of_core')[0]
$bodyDimensionsValid=@($caseDetails | ForEach-Object { $_.chair_bodies } | Where-Object { -not (([Math]::Abs($_.w-1.5)-lt1e-6-and[Math]::Abs($_.d-1.6666666667)-lt1e-6)-or([Math]::Abs($_.w-1.6666666667)-lt1e-6-and[Math]::Abs($_.d-1.5)-lt1e-6)) }).Count-eq0
$checks=@([pscustomobject]@{id='three_declared_translations';pass=($rows.Count-eq3);detail='Baseline and owner-authorized M188 east/north one-foot sensitivities are tested.'},[pscustomobject]@{id='documented_chair_body_dimensions';pass=($bodyDimensionsValid-and@($caseDetails|Where-Object{$_.chair_bodies.Count-ne4}).Count-eq0);detail='Every case retains exactly four 18 x 20-in chair-body envelopes.'},[pscustomobject]@{id='all_furniture_and_pullouts_inside_program_block';pass=(@($rows|Where-Object{-not$_.all_bodies_and_pullouts_inside_11_by_10}).Count-eq0);detail='Every unchanged table/chair body and 36-in pull-out proxy stays inside the 11 x 10-ft study block.'},[pscustomobject]@{id='route_search_keeps_36in_width';pass=(@($rows|Where-Object{$_.route_width_in-ne36-or$_.grid_step_ft-ne0.25}).Count-eq0);detail='M186 retains its exact quarter-foot grid and 36-in route width.'},[pscustomobject]@{id='selected_d_unchanged';pass=($hashes[$selected]-eq'516d6d17e5b6ed6c8ec8cbf7a925cc67c5cc1c0ada194c22ea3fa124e2bb72bb');detail='Selected-D source fingerprint matches protected baseline.'},[pscustomobject]@{id='m06_b_unassigned';pass=([string]$b.status-match'Unassigned');detail='East/pantry-side M-06/B remains unassigned.'},[pscustomobject]@{id='source_hashes_bound';pass=($hashes.Count-eq5);detail='Search, prior placement, specification, selected-D and bath-window sources are fingerprinted.'})
$passed=@($checks|Where-Object pass).Count;$utf8=New-Object Text.UTF8Encoding($false)
$report=[ordered]@{schema='forever-home-m191-dining-pullout-placement-search-v1';status=if($passed-eq$checks.Count){'pass'}else{'fail'};design_result=if(@($rows|Where-Object path_found).Count-eq0){'no_tested_translation_restores_route_with_pullout_proxies'}else{'one_or_more_unapproved_candidates_need_route_review'};method='Three rigid one-foot placement cases generated from the M188 arrangement; each reruns the M186 36-in route search with four 36-in-from-table-edge chair-use rectangles added as obstacles.';source_fingerprints_sha256=$hashes;selected_d_sha256=$hashes[$selected];program_block_local_ft=@(0,14,11,10);target_dining_area_sf=110;cases=$caseDetails.ToArray();summary=$rows.ToArray();checks=[ordered]@{status=if($passed-eq$checks.Count){'pass'}else{'fail'};passed=$passed;total=$checks.Count;items=$checks};limitations=@('The three one-foot translations are finite sensitivities, not a continuous/exhaustive search and not owner-selected furniture positions.','The 36-in pull-out rectangle is a study interpretation of Kitchen_Dining_Porch_Specs.md; exact chair, occupant and motion geometry are absent.','Grid search can only establish a path within the tested quarter-foot centerline lattice and listed static proxies.','The source 42-in preferred distance to walls/porch doors is not checked because physical walls and clear door geometry are unresolved.','Kitchen/dining arrangement, test shell and M-06 windows remain unapproved; B stays unassigned.','No Revit/IFC, selected-D, Incoming RFA, remote state or history is changed.','No code, accessibility, structural-safety, professional, permit or construction-readiness conclusion is made.')}
[IO.File]::WriteAllText((Join-Path $out 'm191-dining-pullout-search.json'),(($report|ConvertTo-Json -Depth 50)+"`n"),$utf8)
[IO.File]::WriteAllText((Join-Path $out 'm191-checks.json'),(($report.checks|ConvertTo-Json -Depth 30)+"`n"),$utf8)
[IO.File]::WriteAllText((Join-Path $out 'm191-options.csv'),((@($rows|ConvertTo-Csv -NoTypeInformation)-join"`n")+"`n"),$utf8)
if($passed-ne$checks.Count){throw "M191 validation failed $passed/$($checks.Count); see $out"}
Write-Output "M191 pass $passed/$($checks.Count); $(@($rows|Where-Object path_found).Count)/$($rows.Count) placements restore a route with chair pull-outs; M-06/B remains unassigned."
